{
  "rules": [
    {
      "category": "security_deposit",
      "title": "Statewide security deposit limit and return regulations",
      "requirement": "Landlords cannot demand or receive a security deposit exceeding one month's rent (or up to two months' rent for qualifying small landlords owning no more than 4 units across two properties). The deposit must be returned within 21 calendar days after vacating, accompanied by an itemized deduction statement and supporting receipts or documentation.",
      "requirement_es": "Los propietarios no pueden exigir ni recibir un depósito de seguridad que supere el equivalente a un mes de alquiler (o hasta dos meses de alquiler para pequeños propietarios que califiquen y posean no más de 4 unidades en dos propiedades). El depósito debe ser devuelto dentro de los 21 días naturales después de desocupar la vivienda, junto con un informe detallado de las deducciones y los recibos o documentación correspondiente.",
      "key_value": {
        "label": "Maximum security deposit",
        "value": "1 month's rent"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Small landlords who are natural persons or LLCs of natural persons owning no more than two residential rental properties totaling no more than four dwelling units may collect up to two months' rent (unless the tenant is a service member)",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "in",
                "value": [
                  "natural_person",
                  "llc"
                ],
                "note": "natural person or LLC in which all members are natural persons"
              },
              {
                "field": "units",
                "operator": "<=",
                "value": 4,
                "note": "collectively include no more than four dwelling units offered for rent across no more than two residential rental properties"
              }
            ]
          }
        },
        {
          "description": "Advance payment of not less than six months' rent where the lease term is six months or longer",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "lease_type",
                "operator": "==",
                "value": "fixed_term",
                "note": "term of the lease is six months or longer"
              }
            ]
          }
        }
      ],
      "effective_date": "2024-07-01",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": "Bad faith claim or retention may subject the landlord to statutory damages of up to twice the amount of the security, in addition to actual damages.",
      "source_citation": "Cal. Civ. Code § 1950.5",
      "quote": {
        "chunk": "c3",
        "start_words": "Except as provided in paragraph (2), (3),",
        "end_words": "on or before initial occupancy."
      },
      "confidence": 0.95
    }
  ]
}
